import { useEffect } from 'react';

const DEFAULT_DESCRIPTION =
  "Vai jūs vēlaties atzīmēt kādu īpašu notikumu vai svētkus? SIA 'Tropiks AZ' iesaka iegādāties kādu no mūsu pirotehniskajiem izstrādājumiem, neaizmirstamu mirkļu radīšanai!";

const DEFAULT_TITLE = 'Noslēdz svētkus ar uguņošanu | Tropiks AZ';

const ensureMeta = (attr, key, content) => {
  let el = document.head.querySelector(`meta[${attr}="${key}"]`);
  if (!content) {
    if (el) el.remove();
    return;
  }
  if (!el) {
    el = document.createElement('meta');
    el.setAttribute(attr, key);
    document.head.appendChild(el);
  }
  el.setAttribute('content', content);
};

const ensureJsonLd = (id, data) => {
  let el = document.getElementById(id);
  if (!data) {
    if (el) el.remove();
    return;
  }
  if (!el) {
    el = document.createElement('script');
    el.type = 'application/ld+json';
    el.id = id;
    document.head.appendChild(el);
  }
  el.textContent = JSON.stringify(data);
};

const usePageMeta = ({
  title,
  description = DEFAULT_DESCRIPTION,
  image,
  path = '',
  noIndex = false,
  exactTitle = false,
  jsonLd,
  jsonLdId = 'page-jsonld',
} = {}) => {
  useEffect(() => {
    const prevTitle = document.title;
    const fullTitle = exactTitle
      ? title || DEFAULT_TITLE
      : title
        ? `${title} | Tropiks AZ`
        : DEFAULT_TITLE;
    document.title = fullTitle;

    const origin = window.location.origin;
    const url = `${origin}${path || window.location.pathname}`;
    const ogImage = image || `${origin}/og-image.png`;

    ensureMeta('name', 'description', description);
    ensureMeta('name', 'robots', noIndex ? 'noindex, nofollow' : 'index, follow');
    ensureMeta('property', 'og:title', fullTitle);
    ensureMeta('property', 'og:description', description);
    ensureMeta('property', 'og:type', 'website');
    ensureMeta('property', 'og:url', noIndex ? origin + '/' : url);
    ensureMeta('property', 'og:image', ogImage);
    ensureMeta('property', 'og:locale', 'lv_LV');
    ensureMeta('property', 'og:site_name', 'Tropiks AZ');
    ensureMeta('name', 'twitter:card', 'summary_large_image');
    ensureMeta('name', 'twitter:title', fullTitle);
    ensureMeta('name', 'twitter:description', description);
    ensureMeta('name', 'twitter:image', ogImage);

    let canonical = document.head.querySelector('link[rel="canonical"]');
    if (!canonical) {
      canonical = document.createElement('link');
      canonical.setAttribute('rel', 'canonical');
      document.head.appendChild(canonical);
    }
    // Soft 404s should not canonicalize to a fake /404 URL
    canonical.setAttribute('href', noIndex ? `${origin}/` : url);

    ensureJsonLd(jsonLdId, jsonLd);

    return () => {
      document.title = prevTitle;
      ensureJsonLd(jsonLdId, null);
    };
  }, [title, description, image, path, noIndex, exactTitle, jsonLd, jsonLdId]);
};

export default usePageMeta;
